import { test, expect } from '@playwright/test';

test.describe('Login Functionality', () => {
  test('should not log in with valid credentials', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.fill('#user_name', 'locked_out_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('input[data-test="submit"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
  });

  test('should display the error message when logging in with locked-out user', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.fill('#user_name', 'locked_out_user');
    await page.fill('#password', 'secret_sauce');
    await page.click('input[data-test="submit"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('[data-test="error"]')).toBeVisible();
    await expect(page.locator('[data-test="error"]')).toHaveTextContaining('Sorry, this user has been locked out');
  });
});
